-- etl-craft: rebuild-metadata
ALTER TABLE CFG_BUSINESS_RULES ALTER COLUMN BUSINESS_RULE_KEY_COLUMN DROP NOT NULL;
ALTER TABLE CFG_BUSINESS_RULES ADD COLUMN BUSINESS_RULE_LEVEL VARCHAR(8) NOT NULL DEFAULT 'ROW';
ALTER TABLE CFG_BUSINESS_RULES ADD CONSTRAINT ck_br_level CHECK (BUSINESS_RULE_LEVEL IN ('ROW','TABLE'));
ALTER TABLE CFG_BUSINESS_RULES ADD CONSTRAINT ck_br_level_key CHECK ((BUSINESS_RULE_LEVEL='ROW' AND NULLIF(trim(BUSINESS_RULE_KEY_COLUMN),'') IS NOT NULL) OR (BUSINESS_RULE_LEVEL='TABLE' AND (BUSINESS_RULE_KEY_COLUMN IS NULL OR BUSINESS_RULE_KEY_COLUMN='') AND BUSINESS_RULE_TYPE<>'INCOMPLETE'));
ALTER TABLE AUD_CFG_BUSINESS_RULES_HISTORY ADD COLUMN BUSINESS_RULE_LEVEL VARCHAR(8) DEFAULT 'ROW';
ALTER TABLE AUD_BUSINESS_RULES_RUN_LOG ADD COLUMN PASSED VARCHAR(1) CHECK (PASSED IN ('Y','N'));
ALTER TABLE AUD_BUSINESS_RULES_RUN_LOG ADD COLUMN OBSERVED VARCHAR(4096) CHECK (length(OBSERVED)<=4096);
ALTER TABLE AUD_BUSINESS_RULES_RUN_LOG ADD COLUMN DETAIL VARCHAR(4096) CHECK (length(DETAIL)<=4096);
COMMENT ON TABLE CFG_BUSINESS_RULES IS 'Checks a BUSINESS_RULES task runs against a warehouse table. ROW rules return target keys; TABLE rules record one PASSED/OBSERVED/DETAIL result.';
COMMENT ON TABLE AUD_BUSINESS_RULES_RUN_LOG IS 'Whether each business rule ran, per task run, with TABLE evidence in PASSED/OBSERVED/DETAIL. ROW flags are in AUD_BUSINESS_RULES_RESULTS.';
